import{I as e,J as t,M as n,_ as r,g as i,h as a,p as o,t as s,u as c}from"./plugin-vue_export-helper-Dy_UwxR5.js";var l=JSON.parse(`{"path":"/forge/BOSS.md/oyzoojfr/","title":"说明 | 原版文档","lang":"zh-CN","frontmatter":{"title":"说明","createTime":"2026/03/11 19:12:21","permalink":"/forge/BOSS.md/oyzoojfr/"},"git":{},"filePathRelative":"forge/说明.md","headers":[]}`),u={name:`说明.md`};function d(s,l,u,d,f,p){let m=e(`Plot`);return n(),o(`div`,null,[l[1]||=a(`<p>整合包基本机制、小特性介绍，大部分内容与游戏任务中相同，建议认真阅读游戏中的游玩前须知，本包对mod内容做了改动，与常规Tetra包略有不同。</p><h2 id="阶段性" tabindex="-1"><a class="header-anchor" href="#阶段性"><span>阶段性</span></a></h2><p>锻造之旅为阶段式流程，且<span style="color:red;background-color:blanchedalmond;">锁阶段</span>，未达成阶段要求前无法使用或进入下一阶段的物品或维度。<br> 请时刻注意屏幕内左下角的文字提示：<span style="color:chocolate;background-color:antiquewhite;">二阶段才能进入该维度</span></p><div class="hint-container warning"><p class="hint-container-title">注意</p><p>一阶段内无法使用锻造锤，进入其他维度传送门会被强制退回主世界</p></div><div class="hint-container warning"><p class="hint-container-title">注意</p><p>一阶段请不要跳进末地传送门，会卡在传送门内，导致反复在主世界与末地间传送。</p></div><h2 id="特性" tabindex="-1"><a class="header-anchor" href="#特性"><span>特性</span></a></h2><p><strong>副手存在物品时伤害减少</strong>，主手和副手同时存在Tetra模组的物品时伤害会减少40%。<br><span style="color:blue;">Tetra盾牌除外</span>。</p><blockquote><p>原因：</p><ul><li>主手加成加上加上特定副手武器会导致输出手段过于单调。</li><li>为了武器和攻击伤害的多样性，对此部分进行额外限制。</li></ul></blockquote>`,8),c(`p`,null,[r(m,null,{default:t(()=>[...l[0]||=[i(`其实是主副武器加成多次将作者的预计伤害击碎了`,-1)]]),_:1})]),l[2]||=a(`<h2 id="锻造师等级-已弃用" tabindex="-1"><a class="header-anchor" href="#锻造师等级-已弃用"><span>锻造师等级(<strong>已弃用</strong>)</span></a></h2><p>整合包加入特殊机制“锻造师等级” 锻造师等级分为四级：</p><ul><li>学徒 | 护甲锻造保留打磨</li><li>入门 | 锻造的武器带有高质量1，护甲锻造保留打磨</li><li>精英 | 锻造的武器带有高质量2，护甲锻造保留打磨</li><li>传奇 | 锻造的武器带有高质量3，护甲锻造保留打磨</li></ul><p><strong>高质量：每级+5%攻击力，+1挖掘效率。</strong></p><p><strong>升级方式：</strong></p><ul><li>每次使用加工台锻造有10%概率+1锻造经验</li><li>满10点锻造经验可进入下一等级</li></ul><h2 id="创造飞行" tabindex="-1"><a class="header-anchor" href="#创造飞行"><span>创造飞行</span></a></h2><p>除了包内提供的几种飞行方式，其它自行添加的mod所提供的飞行方式无法生效。</p><h2 id="怪物" tabindex="-1"><a class="header-anchor" href="#怪物"><span>怪物</span></a></h2><p><strong>一阶段：</strong></p><ul><li>主世界普通怪物血量 x2</li><li>精英怪血量 x5</li><li>BOSS血量 x10</li><li>灾变boss进行限伤</li></ul><p><strong>二阶段：</strong></p><ul><li>怪物血量 x10</li><li>BOSS血量微调约 x20</li><li>怪物伤害微调约 x4</li></ul><p><strong>三阶段：</strong></p><ul><li>怪物血量 +1k</li><li>BOSS血量 +1w</li><li>护甲 +80</li><li>怪物每秒恢复360血</li><li>末地生物伤害额外增加 1.5</li></ul><h2 id="关于如何前往下一阶段" tabindex="-1"><a class="header-anchor" href="#关于如何前往下一阶段"><span>关于如何前往下一阶段</span></a></h2><ul><li>一阶段完成“灾变之心”任务后，后续7个BOSS击杀4个即可进入二阶段</li><li>二阶段完成帕斯特之梦中风之旅途维度或灯影之下维度其一获得“通行证”即可进入三阶段</li></ul>`,17)])}var f=s(u,[[`render`,d]]);export{l as _pageData,f as default};